/**
 * Every combat sound the client plays (#104). This is the single list: each
 * id has exactly one file at `public/sfx/<id>.mp3`, generated by
 * `scripts/assets/sfx.sh`, and `sfx-files.test.ts` holds the two together.
 */
export const SOUND_IDS = [
  "cast-self",
  "cast-target",
  "hit-dealt",
  "hit-taken",
  "heal",
  "interrupt",
  "interrupt-missed",
  "death",
  "refused",
  "weapon-swing",
  "bow-release",
] as const;

export type SoundId = (typeof SOUND_IDS)[number];
